-- D12 written comment DEV postflight. READ-ONLY: one SELECT, no write, no lock, no function with a side effect. Run it against canonical DEV right after the ONE-statement application (and at any time later).
-- GENERATED by supabase/proofs/d12/build_d12.py from the pin tables of the application (d12_pins.json, d12_preimage.json and the new function bodies): do not edit by hand (`--check` fails on any difference).
-- Returns ONE row of JSON: how many pins were compared, every part of the applied state that does not hold ("problems": an empty array means the application is exactly in place and the closure certificate is
-- bound, certified and ready) and the live certificate facts. The disposable proof runs this same file on the chain the application produced and requires an empty list.
with
  metadata_pins(signature, metadata_md5) as (values
{{METADATA_PINS}}
  ),
  unchanged_body_pins(signature, body_md5) as (values
{{UNCHANGED_BODY_PINS}}
  ),
  applied_body_pins(signature, body_md5) as (values
{{APPLIED_BODY_PINS}}
  ),
  new_function_pins(signature, body_md5, language_name, volatility, definer, strict_function, result_type, acl) as (values
{{NEW_FUNCTION_PINS}}
  ),
  composite_pins(signature, acl, config, definer, volatility, language_name, result_type, strict_function) as (values
{{COMPOSITE_PINS}}
  ),
  cert as (
    select (select count(*) from private.closure_source_v5) as source_rows,
           (select count(*) from private.closure_erasure_source_v5) as erasure_rows,
           (select sha256 from private.closure_source_v5 where singleton) as certified,
           (select sha256 from private.closure_erasure_source_v5 where singleton) as erasure_sha,
           private.closure_source_digest_v5() as live_digest,
           private.retention_ai_source_ready() as ready,
           private.closure_erasure_binding_v5()->>'sourceSha256' as bound
  ),
  problems as (
    select 'METADATA_DRIFT' as kind, pin.signature as detail
    from metadata_pins pin
    where (select md5(((to_jsonb(p)-'oid'-'pronamespace'-'proowner'-'prolang'-'proacl'-'prosrc')
        ||jsonb_build_object('namespace',n.nspname,'owner',pg_get_userbyid(p.proowner),'language',l.lanname,'acl',p.proacl::text))::text)
        from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang
        where p.oid=to_regprocedure(pin.signature)) is distinct from pin.metadata_md5
    union all
    select 'UNCHANGED_BODY_DRIFT', pin.signature
    from unchanged_body_pins pin
    where (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5
    union all
    select 'APPLIED_BODY_DRIFT', pin.signature
    from applied_body_pins pin
    where (select md5(replace(prosrc,E'\r\n',E'\n')) from pg_proc where oid=to_regprocedure(pin.signature)) is distinct from pin.body_md5
    union all
    select 'NEW_FUNCTION_DRIFT', pin.signature
    from new_function_pins pin
    where not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature) and {{NEW_FUNCTION_PREDICATE}})
    union all
    select 'LEGACY_REVIEW_FUNCTION_OVERLOAD', 'rpc_submit_agreement_review or rpc_get_my_agreement_review has a second overload'
    where (select count(*) from pg_proc where pronamespace='public'::regnamespace and proname in('rpc_submit_agreement_review','rpc_get_my_agreement_review'))<>2
    union all
    select 'READINESS_DRIFT', 'private.retention_ai_source_ready() differs from the predecessor by more than its one certified literal'
    where not exists(select 1 from pg_proc p, cert c where p.oid=to_regprocedure('private.retention_ai_source_ready()')
      and (length(p.prosrc)-length(replace(p.prosrc,c.certified,'')))=length(c.certified)
      and md5(replace(replace(p.prosrc,E'\r\n',E'\n'),c.certified,'__CERTIFIED_SOURCE__'))='{{READINESS_PLACEHOLDER_MD5}}')
    union all
    select 'PROJECTION_SHA_DRIFT', 'private.data_export_projection_sha_v5()'
    where private.data_export_projection_sha_v5() is distinct from '{{PROJECTION_SHA_AFTER}}'
    union all
    select 'COMMENT_TABLE_DRIFT', 'private.{{TABLE}}'
    where {{TABLE_SHAPE_BAD}}
    union all
    select 'TRIGGER_DRIFT', 'private.{{TABLE}} triggers'
    where {{TRIGGERS_BAD}}
    union all
    select 'ROSTER_DRIFT', 'the redaction roster does not end with the comment table or the scope/patch do not cover it'
    where cardinality(private.closure_redaction_relations_v5())<>{{ROSTER_AFTER}}
      or (private.closure_redaction_relations_v5())[{{ROSTER_AFTER}}] is distinct from 'private.{{TABLE}}'
      or (private.closure_redaction_relations_v5())[{{ROSTER_BEFORE}}] is distinct from 'public.app_accounts'
      or 'private.agreement_reviews'=any(private.closure_redaction_relations_v5())
      or private.closure_redaction_scope_v5('private.{{TABLE}}') is distinct from 't.author_account_id=$1'
      or private.closure_redaction_patch_v5('private.{{TABLE}}','{}'::jsonb,'00000000-0000-0000-0000-000000000000'::uuid,'00000000-0000-0000-0000-000000000000'::uuid)
         is distinct from jsonb_build_object('operation','DELETE','patch','{}'::jsonb)
    union all
    select 'RETENTION_CATALOG_DRIFT', 'AGREEMENT_REVIEWS'
    where (select relations from private.closure_dataset_catalog_v5 where data_class='AGREEMENT_REVIEWS') is distinct from array['private.agreement_reviews','private.{{TABLE}}']::text[]
      or (select count(*) from private.retention_data_classes where required and active)<>15
    union all
    select 'EXPORT_CATALOG_DRIFT', 'private.data_export_dataset_catalog()'
    where jsonb_array_length(private.data_export_dataset_catalog())<>52
      or (select v->'fields' from jsonb_array_elements(private.data_export_dataset_catalog()) v where v->>'key'='ownAgreementReviews') is distinct from '["agreementId","createdAt","id","rating","tags","comment"]'::jsonb
      or position('OWN_ACCOUNT_V5_10' in (select prosrc from pg_proc where oid=to_regprocedure('private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)')))=0
      or position('OWN_ACCOUNT_V5_9' in (select prosrc from pg_proc where oid=to_regprocedure('private.data_export_snapshot(uuid,uuid,jsonb,timestamptz)')))<>0
      or position('OWN_ACCOUNT_V5_10' in (select prosrc from pg_proc where oid=to_regprocedure('private.data_export_policy_binding()')))=0
      or position('OWN_ACCOUNT_V5_9' in (select prosrc from pg_proc where oid=to_regprocedure('private.data_export_policy_binding()')))<>0
    union all
    select 'STAR_TABLE_DRIFT', 'private.agreement_reviews is not the unchanged immutable star table'
    where {{STAR_TABLE_BAD}}
    union all
    select 'COMPOSITE_METADATA_DRIFT', pin.signature
    from composite_pins pin
    where not exists(select 1 from pg_proc p where p.oid=to_regprocedure(pin.signature) and {{COMPOSITE_PREDICATE}})
    union all
    select 'RETENTION_CLASS_DESCRIPTION_DRIFT', 'the description of the retention class {{RETENTION_CLASS_CODE}} is not the text this package sets'
    where (select description from private.retention_data_classes where code='{{RETENTION_CLASS_CODE}}' and required and active) is distinct from {{RETENTION_DESCRIPTION_NEW}}
    union all
    select 'COMMENT_TABLE_PUBLISHED', 'the comment table is in a publication, or a FOR ALL TABLES publication exists: the text could be streamed'
    where {{PUBLICATION_BAD}}
    union all
    select 'CERTIFICATE_CARDINALITY', 'closure_source_v5 and closure_erasure_source_v5 must hold exactly one row each'
    from cert where source_rows<>1 or erasure_rows<>1
    union all
    select 'CERTIFICATE_NOT_BOUND', 'the certificate, the live digest, the erasure source row, the readiness and the binding must all agree'
    from cert where certified is null or certified is distinct from live_digest or certified is distinct from erasure_sha or ready is distinct from true or bound is distinct from certified
    union all
    select 'CERTIFICATE_NOT_MOVED', 'the certified digest must differ from the pre-D12 DEV value when the chain is DEV ({{CERTIFIED_DIGEST}})'
    from cert where certified='{{CERTIFIED_DIGEST}}'
    union all
    select 'FUNCTION_AUTHORITY_DRIFT', 'a new function is reachable by a role it must not be reachable by, or the table is reachable by a client role'
    where has_function_privilege('anon','private.retention_ai_source_ready()','EXECUTE') or has_function_privilege('authenticated','private.retention_ai_source_ready()','EXECUTE')
      or exists(select 1 from unnest(array[{{NEW_FUNCTION_SIGNATURES}}]::text[]) x where has_function_privilege('anon',x,'EXECUTE'))
      or exists(select 1 from unnest(array[{{CLIENT_FUNCTION_SIGNATURES}}]::text[]) x where not has_function_privilege('authenticated',x,'EXECUTE') or has_function_privilege('service_role',x,'EXECUTE'))
      or exists(select 1 from unnest(array[{{PRIVATE_FUNCTION_SIGNATURES}}]::text[]) x where has_function_privilege('authenticated',x,'EXECUTE') or has_function_privilege('service_role',x,'EXECUTE'))
      or has_function_privilege('authenticated','{{SERVICE_FUNCTION_SIGNATURE}}','EXECUTE') or not has_function_privilege('service_role','{{SERVICE_FUNCTION_SIGNATURE}}','EXECUTE')
      or exists(select 1 from unnest(array['anon','authenticated','service_role']) r where has_table_privilege(r,'private.{{TABLE}}','SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'))
    union all
    select 'RETRIED_SQLSTATE_IN_A_NEW_BODY', 'a new function mentions the SQLSTATE that PostgREST 14 re-executes without end (a deterministic conflict must be PT409; no new body mentions it at all)'
    where exists(select 1 from unnest(array[{{NEW_FUNCTION_SIGNATURES}}]::text[]) x join pg_proc p on p.oid=to_regprocedure(x) where position('40001' in p.prosrc)>0)
    union all
    select 'CLOSURE_IN_FLIGHT', 'a closure execution is EXECUTING'
    where exists(select 1 from private.closure_executions_v5 where state='EXECUTING')
  )
select jsonb_build_object(
  'unit', 'D12_DEV_POSTFLIGHT',
  'metadataPinsChecked', (select count(*) from metadata_pins),
  'unchangedBodyPinsChecked', (select count(*) from unchanged_body_pins),
  'appliedBodyPinsChecked', (select count(*) from applied_body_pins),
  'newFunctionPinsChecked', (select count(*) from new_function_pins),
  'problems', coalesce((select jsonb_agg(jsonb_build_object('kind',kind,'detail',detail) order by kind,detail) from problems), '[]'::jsonb),
  'certifiedSource', (select certified from cert),
  'liveDigest', (select live_digest from cert),
  'ready', (select ready from cert),
  'erasureBindingMatches', (select bound is not distinct from certified from cert),
  'redactionRelations', cardinality(private.closure_redaction_relations_v5()),
  'exportDatasets', jsonb_array_length(private.data_export_dataset_catalog()),
  'exportProjectionSha', private.data_export_projection_sha_v5(),
  'exportPolicyBindingIsNull', private.data_export_policy_binding() is null,
  'commentRows', (select count(*) from private.{{TABLE}}),
  'retentionClassDescription', (select description from private.retention_data_classes where code='{{RETENTION_CLASS_CODE}}'),
  'closureHistoryNamingTheCommentTable', (select count(*) from private.closure_redaction_steps_v5 where relation_name='private.{{TABLE}}'),
  'reviews', (select count(*) from private.agreement_reviews),
  'reviewIdHashBaseline', (select md5(string_agg(id::text||':'||input_hash,',' order by id)) from private.agreement_reviews),
  'authenticatedHasPrivateSchemaUsage', has_schema_privilege('authenticated','private','USAGE'),
  'ledgerRows', (select count(*) from supabase_migrations.schema_migrations),
  'latestLedgerVersion', (select max(version) from supabase_migrations.schema_migrations),
  'serverVersion', current_setting('server_version'),
  'checkedAt', to_char(clock_timestamp() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"')
) as postflight;
